<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/config/bootstrap.php';require dirname(__DIR__,2).'/app/admin.php';$admin=admin_require($pdo);$comments=$pdo->query('SELECT c.*,p.title FROM comments c JOIN posts p ON p.id=c.post_id ORDER BY c.created_at DESC LIMIT 200')->fetchAll();
admin_header('Comments',$admin);admin_show_flash(); ?><section class="content-card"><h2>Reader comments</h2><p>Review comments before they appear publicly.</p><div class="table-wrap"><table><thead><tr><th>Reader</th><th>Comment</th><th>Article</th><th>Status</th><th>Moderation</th></tr></thead><tbody><?php foreach($comments as $c): ?><tr><td><?= e($c['name']) ?><br><small><?= e($c['email']) ?></small></td><td><?= e($c['body']) ?></td><td><?= e($c['title']) ?></td><td><?= e($c['status']) ?></td><td><form method="post" action="<?= e(admin_url('comments/moderate.php')) ?>"><?= admin_csrf_field() ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><select name="status"><option value="pending">Pending</option><option value="approved" <?= $c['status']==='approved'?'selected':'' ?>>Approve</option><option value="spam">Spam</option></select><button class="button small">Save</button></form></td></tr><?php endforeach ?><?php if(!$comments): ?><tr><td colspan="5">No comments yet.</td></tr><?php endif ?></tbody></table></div></section><?php admin_footer(); ?>
